          selectedOpportunity={selectedOpportunity}
          stageJump={stageJump}
          mode={mode}
        />
        <AgentControl mode={mode} setMode={setMode} />
      </main>
      <FinalPaperViewer task={task} currentStage={currentStage} />
    </div>
  );
